<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\Menu;use App\Services\CmsService;final class MenuController extends AdminController{public function index(Request $e):Response{return $this->view('admin/menus',['menus'=>Menu::all('id'),'meta'=>['title'=>t('admin.menus')]]);}public function save(Request $O):Response{$s=$O->str('slug');$Q=Menu::findBy('slug',$s);$g=json_decode((string)$O->input('items_json','[]'),true);$e=[];foreach(is_array($g)?$g:[]as $i){if(!is_array($i)){continue;}$Y=CmsService::safeUrl((string)($i['url']??'/'));$e[]=['key'=>is_string($i['key']??null)?substr($i['key'],0,64):'','label'=>$this->multilang($i['label']??[]),'url'=>$Y];}if($Q){Menu::update((int)$Q['id'],['items'=>$e,'name'=>$O->str('name')?:$Q['name'],'updated_at'=>now()]);}elseif(preg_match('/^[a-z0-9-]+$/',$s)){Menu::create(['slug'=>$s,'name'=>$O->str('name')?:$s,'items'=>$e,'updated_at'=>now()]);}AuditLog::log('admin.menu_save',$s);$this->flash('success',t('common.saved'));return $this->redirect('/admin/menus');}}